// Elementary properties of inverse trigonometric functions are deleted (2026-27) and appear nowhere:
// every value is found from the principal value branches (definition) and read from graphs.
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { setUnit, topic, deck, sl, plot, table, flow, geom, build, chapterTests, r } from '../../cbse-12-mathematics-ch01/src/lib.mjs';

setUnit('cbse-12-mathematics-ch02');
const { P, piTex, gAtan } = await import('./questions.mjs');
const DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const S3 = Math.sqrt(3);
const H = P / 2;
const t = (v) => `$${piTex(v)}$`; // exact cell text computed from the value itself

// ---------------------------------------------------------------- plots (every marked point is checked on its curve)
const pSinFull = plot({ x: [-2 * P - 0.3, 2 * P + 0.3], y: [-1.5, 1.5], fns: [{ expr: 'sin(x)', label: r`$y = \sin x$` }, { expr: '0.5', label: r`$y = \dfrac12$` }], pts: [[-11 * P / 6, 0.5, 'A'], [-7 * P / 6, 0.5, 'B'], [P / 6, 0.5, 'C'], [5 * P / 6, 0.5, 'D']] }, 'The sine wave from minus 2 pi to 2 pi with the horizontal line y equals one half. The line cuts the wave at four marked points A, B, C and D, so four different angles in view have the same sine.', r`One output, many inputs: $\sin x$ is not one-one on $\mathbb{R}$.`);
const pSinRestricted = plot({ x: [-2, 2], y: [-1.5, 1.5], fns: [{ expr: 'sin(x)', label: r`$y = \sin x$`, domain: [-H, H] }], pts: [[-H, -1, r`$\left(-\dfrac{\pi}{2}, -1\right)$`], [0, 0, '(0, 0)'], [P / 6, 0.5, r`$\left(\dfrac{\pi}{6}, \dfrac12\right)$`], [H, 1, r`$\left(\dfrac{\pi}{2}, 1\right)$`]] }, 'Only the piece of the sine curve from x equal to minus pi over 2 to pi over 2 is drawn. It rises steadily from (minus pi over 2, minus 1) through the origin to (pi over 2, 1), taking every value from minus 1 to 1 exactly once.', r`On $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$ sine is one-one and onto $[-1, 1]$.`);
const pReflect = plot({ x: [-2, 2], y: [-2, 2], fns: [{ expr: 'sin(x)', label: r`$y = \sin x$`, domain: [-H, H] }, { expr: 'asin(x)', label: r`$y = \sin^{-1} x$`, domain: [-1, 1] }, { expr: 'x', label: '$y = x$' }], pts: [[P / 6, 0.5, 'P'], [0.5, P / 6, 'Q'], [H, 1, 'R'], [1, H, 'S']] }, 'Three graphs: the restricted sine curve, its mirror image y equals sin inverse x, and the line y equals x between them. Point P on the sine curve and point Q on the inverse curve are mirror images, as are R and S.', r`Swap the coordinates: $P\left(\dfrac{\pi}{6}, \dfrac12\right)$ becomes $Q\left(\dfrac12, \dfrac{\pi}{6}\right)$.`);
const asinPts = [[-1, -H], [-0.5, -P / 6], [0, 0], [0.5, P / 6], [1, H]];
const pAsin = plot({ x: [-1.5, 1.5], y: [-2, 2], fns: [{ expr: 'asin(x)', label: r`$y = \sin^{-1} x$`, domain: [-1, 1] }], pts: asinPts.map(([x, y]) => [x, y, x === 0 ? '(0, 0)' : `$\\left(${x < 0 ? '-' : ''}${Math.abs(x) === 1 ? '1' : '\\dfrac12'}, ${piTex(y)}\\right)$`]) }, 'The graph of y equals sin inverse x for x from minus 1 to 1. It rises from (minus 1, minus pi over 2) through (minus one half, minus pi over 6), the origin and (one half, pi over 6) to (1, pi over 2), steep at both ends.', r`$y = \sin^{-1} x$: domain $[-1, 1]$, range $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$, increasing.`);
const pWE1 = plot({ x: [-1.5, 1.5], y: [-2, 2], fns: [{ expr: 'asin(x)', label: r`$y = \sin^{-1} x$`, domain: [-1, 1] }], pts: [[-0.5, -P / 6, r`$\left(-\dfrac12, -\dfrac{\pi}{6}\right)$`]] }, 'The graph of y equals sin inverse x with the point at x equal to minus one half marked. Its height is minus pi over 6, below the x-axis.', r`$\sin^{-1}\left(-\dfrac12\right) = -\dfrac{\pi}{6}$: a negative input gives a negative angle.`);
const pCosRestricted = plot({ x: [-0.5, 3.6], y: [-1.5, 1.5], fns: [{ expr: 'cos(x)', label: r`$y = \cos x$`, domain: [0, P] }], pts: [[0, 1, '(0, 1)'], [P / 3, 0.5, r`$\left(\dfrac{\pi}{3}, \dfrac12\right)$`], [H, 0, r`$\left(\dfrac{\pi}{2}, 0\right)$`], [P, -1, r`$(\pi, -1)$`]] }, 'The cosine curve drawn only from x equal to 0 to pi. It falls steadily from (0, 1) through (pi over 2, 0) to (pi, minus 1), taking every value from minus 1 to 1 exactly once.', r`On $[0, \pi]$ cosine is one-one and onto $[-1, 1]$.`);
const acosPts = [[-1, P], [-0.5, 2 * P / 3], [0, H], [0.5, P / 3], [1, 0]];
const pAcos = plot({ x: [-1.5, 1.5], y: [-0.5, 3.5], fns: [{ expr: 'acos(x)', label: r`$y = \cos^{-1} x$`, domain: [-1, 1] }], pts: acosPts.map(([x, y]) => [x, y, y === 0 ? '(1, 0)' : `$\\left(${x < 0 ? '-' : ''}${Math.abs(x) === 1 ? '1' : x === 0 ? '0' : '\\dfrac12'}, ${piTex(y)}\\right)$`]) }, 'The graph of y equals cos inverse x for x from minus 1 to 1. It falls from (minus 1, pi) through (minus one half, 2 pi over 3), (0, pi over 2) and (one half, pi over 3) to (1, 0). Every point is on or above the x-axis.', r`$y = \cos^{-1} x$: domain $[-1, 1]$, range $[0, \pi]$, decreasing.`);
const pWE2 = plot({ x: [-1.5, 1.5], y: [-0.5, 3.5], fns: [{ expr: 'acos(x)', label: r`$y = \cos^{-1} x$`, domain: [-1, 1] }], pts: [[-Math.SQRT1_2, 3 * P / 4, r`$\left(-\dfrac{1}{\sqrt2}, \dfrac{3\pi}{4}\right)$`]] }, 'The graph of y equals cos inverse x with the point at x equal to minus 1 over root 2 marked at height 3 pi over 4, above pi over 2 because the input is negative.', r`A negative input to $\cos^{-1}$ gives an obtuse angle.`);
const pTanRestricted = plot({ x: [-2, 2], y: [-6, 6], fns: [{ expr: 'tan(x)', label: r`$y = \tan x$`, domain: [-1.4, 1.4] }], pts: [[-P / 4, -1, r`$\left(-\dfrac{\pi}{4}, -1\right)$`], [0, 0, '(0, 0)'], [P / 4, 1, r`$\left(\dfrac{\pi}{4}, 1\right)$`]] }, 'The tangent curve on the open interval from minus pi over 2 to pi over 2, rising from very large negative values through (minus pi over 4, minus 1), the origin and (pi over 4, 1) to very large positive values, with dashed vertical asymptotes at both ends.', r`On $\left(-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right)$ tangent is one-one and takes every real value.`);
pTanRestricted.spec.vlines = [{ x: -H, label: r`$x = -\dfrac{\pi}{2}$`, dashed: true }, { x: H, label: r`$x = \dfrac{\pi}{2}$`, dashed: true }];
const pAtanDeck = plot({ x: [-6, 6], y: [-2, 2], fns: [{ expr: 'atan(x)', label: r`$y = \tan^{-1} x$` }], pts: [[-S3, -P / 3, r`$\left(-\sqrt3, -\dfrac{\pi}{3}\right)$`], [0, 0, '(0, 0)'], [1, P / 4, r`$\left(1, \dfrac{\pi}{4}\right)$`], [S3, P / 3, r`$\left(\sqrt3, \dfrac{\pi}{3}\right)$`]] }, 'The graph of y equals tan inverse x, an S-shaped curve through the origin, (1, pi over 4) and (root 3, pi over 3), squeezed between the dashed horizontal asymptotes y equals pi over 2 and y equals minus pi over 2.', r`$y = \tan^{-1} x$: domain $\mathbb{R}$, range $\left(-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right)$, increasing.`);
pAtanDeck.spec.hlines = [{ y: H, label: r`$y = \dfrac{\pi}{2}$`, dashed: true }, { y: -H, label: r`$y = -\dfrac{\pi}{2}$`, dashed: true }];
const pAll3 = plot({ x: [-3, 3], y: [-2, 3.5], fns: [{ expr: 'asin(x)', label: r`$\sin^{-1} x$`, domain: [-1, 1] }, { expr: 'acos(x)', label: r`$\cos^{-1} x$`, domain: [-1, 1] }, { expr: 'atan(x)', label: r`$\tan^{-1} x$` }], pts: [[0, 0, '(0, 0)'], [0, H, r`$\left(0, \dfrac{\pi}{2}\right)$`]] }, 'Three inverse functions on one set of axes: sin inverse x rising and cos inverse x falling, both only between x equal to minus 1 and 1, and tan inverse x continuing across the whole picture, flattening out at both ends.', 'Short curves for $\\sin^{-1}$ and $\\cos^{-1}$ (domain $[-1, 1]$); a long one for $\\tan^{-1}$ (domain $\\mathbb{R}$).');
const pReflectCos = plot({ x: [-1.5, 3.6], y: [-1.5, 3.6], fns: [{ expr: 'cos(x)', label: r`$y = \cos x$`, domain: [0, P] }, { expr: 'acos(x)', label: r`$y = \cos^{-1} x$`, domain: [-1, 1] }, { expr: 'x', label: '$y = x$' }], pts: [[0, 1, '(0, 1)'], [1, 0, '(1, 0)'], [P, -1, r`$(\pi, -1)$`], [-1, P, r`$(-1, \pi)$`], [P / 3, 0.5, 'P'], [0.5, P / 3, 'Q']] }, 'The cosine curve on 0 to pi and its mirror image y equals cos inverse x across the line y equals x. Matching points are marked: (0, 1) with (1, 0), (pi, minus 1) with (minus 1, pi), and P with Q.', r`Every point $(a, b)$ of the cosine piece gives a point $(b, a)$ of $y = \cos^{-1} x$.`);
const pWE5 = plot({ x: [-1.5, 1.5], y: [-2, 2], fns: [{ expr: 'asin(x)', label: r`$y = \sin^{-1} x$`, domain: [-1, 1] }], pts: [[0.6, Math.asin(0.6), 'P'], [0.8, Math.asin(0.8), 'Q']] }, 'The rising graph of y equals sin inverse x with two points marked: P at x equal to 0.6 and Q, higher up, at x equal to 0.8.', r`Further right on a rising graph means higher: $\sin^{-1} 0.8 > \sin^{-1} 0.6$.`);
const pWE6 = plot({ x: [-0.3, 3.5], y: [-0.5, 1.5], fns: [{ expr: 'sin(x)', label: r`$y = \sin x$`, domain: [0, P] }], pts: [[3 * P / 10, Math.sin(3 * P / 10), 'A'], [7 * P / 10, Math.sin(7 * P / 10), 'B']] }, 'The sine curve from 0 to pi, an arch. Points A at x equal to 3 pi over 10 and B at x equal to 7 pi over 10 sit at the same height, mirror images in the dashed line x equals pi over 2.', r`$\sin\dfrac{7\pi}{10} = \sin\dfrac{3\pi}{10}$, and only $\dfrac{3\pi}{10}$ is in the principal range.`);
pWE6.spec.vlines = [{ x: H, label: r`$x = \dfrac{\pi}{2}$`, dashed: true }];
const pWE8 = plot({ x: [-2, 2], y: [-2, 2], fns: [{ expr: 'atan(3x)', label: r`$y = \tan^{-1}(3x)$` }], pts: [[-1 / S3, -P / 3, r`$\left(-\dfrac{1}{\sqrt3}, -\dfrac{\pi}{3}\right)$`]] }, 'The graph of y equals tan inverse of 3 x, an S-shaped curve through the origin, with the point at height minus pi over 3 marked at x equal to minus 1 over root 3.', r`The solution of $\tan^{-1}(3x) = -\dfrac{\pi}{3}$ is where the curve reaches height $-\dfrac{\pi}{3}$.`);
const pDomain = plot({ x: [0, 3], y: [-2, 3], xl: 'x', yl: 'input 3 − 2x', fns: [{ expr: '3 - 2x', label: '$u = 3 - 2x$' }], pts: [[1, 1, '(1, 1)'], [2, -1, '(2, −1)']] }, 'The straight line u equals 3 minus 2 x with dashed horizontal lines at u equals 1 and u equals minus 1. The line lies between them for x from 1 to 2, marked by the points (1, 1) and (2, minus 1).', r`The input $3 - 2x$ stays in $[-1, 1]$ exactly for $1 \le x \le 2$.`);
pDomain.spec.hlines = [{ y: 1, label: '$u = 1$', dashed: true }, { y: -1, label: '$u = -1$', dashed: true }];

// ---------------------------------------------------------------- tables, flows, geometry
const branchTable = table(['Function', 'Domain', 'Principal value branch (range)'], [
  [r`$\sin^{-1} x$`, '$[-1, 1]$', r`$\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$`],
  [r`$\cos^{-1} x$`, '$[-1, 1]$', r`$[0, \pi]$`],
  [r`$\tan^{-1} x$`, r`$\mathbb{R}$`, r`$\left(-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right)$`],
  [r`$\operatorname{cosec}^{-1} x$`, r`$\mathbb{R} - (-1, 1)$`, r`$\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right] - \{0\}$`],
  [r`$\sec^{-1} x$`, r`$\mathbb{R} - (-1, 1)$`, r`$[0, \pi] - \left\{\dfrac{\pi}{2}\right\}$`],
  [r`$\cot^{-1} x$`, r`$\mathbb{R}$`, r`$(0, \pi)$`],
], 'Table of the six inverse trigonometric functions. Sin inverse and cos inverse have domain minus 1 to 1, with ranges minus pi over 2 to pi over 2 and 0 to pi. Tan inverse and cot inverse accept all reals, with ranges the open intervals minus pi over 2 to pi over 2 and 0 to pi. Cosec inverse and sec inverse accept reals outside the open interval minus 1 to 1; their ranges are those of sin inverse without 0 and of cos inverse without pi over 2.', 'Learn this table: every principal value question uses one row of it.');
const xs5 = [-1, -0.5, 0, 0.5, 1];
const xTex = ['$-1$', r`$-\dfrac12$`, '$0$', r`$\dfrac12$`, '$1$'];
const sinValTable = table(['$x$', ...xTex], [[r`$\sin^{-1} x$`, ...xs5.map((x) => t(Math.asin(x)))]], 'Table of sin inverse x: at x equal to minus 1, minus one half, 0, one half and 1 the values are minus pi over 2, minus pi over 6, 0, pi over 6 and pi over 2.', r`Negative inputs give negative angles; all values lie in $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$.`);
const cosValTable = table(['$x$', ...xTex], [[r`$\cos^{-1} x$`, ...xs5.map((x) => t(Math.acos(x)))]], 'Table of cos inverse x: at x equal to minus 1, minus one half, 0, one half and 1 the values are pi, 2 pi over 3, pi over 2, pi over 3 and 0.', r`All values lie in $[0, \pi]$; negative inputs give obtuse angles.`);
const otherTable = table(['Expression', 'Condition on $y$', 'Principal value'], [
  [r`$\cot^{-1}(-\sqrt3)$`, r`$\cot y = -\sqrt3$, $y \in (0, \pi)$`, t(Math.PI + Math.atan(-1 / S3))],
  [r`$\operatorname{cosec}^{-1}\left(\dfrac{2}{\sqrt3}\right)$`, r`$\sin y = \dfrac{\sqrt3}{2}$, $y \in \left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right] - \{0\}$`, t(Math.asin(S3 / 2))],
], 'Worked table: cot inverse of minus root 3 is 5 pi over 6, because cot of 5 pi over 6 is minus root 3 and 5 pi over 6 is between 0 and pi. Cosec inverse of 2 over root 3 is pi over 3, because sine of pi over 3 is root 3 over 2.', 'Change to a ratio you know, then place the angle in the right range.');
const thetas = [P / 6, 5 * P / 6, 7 * P / 6, -P / 3];
const compTable = table([r`$\theta$`, r`$\sin\theta$`, r`$\sin^{-1}(\sin\theta)$`, r`Equals $\theta$?`], [
  [t(thetas[0]), r`$\dfrac12$`, t(Math.asin(Math.sin(thetas[0]))), 'yes'],
  [t(thetas[1]), r`$\dfrac12$`, t(Math.asin(Math.sin(thetas[1]))), 'no'],
  [t(thetas[2]), r`$-\dfrac12$`, t(Math.asin(Math.sin(thetas[2]))), 'no'],
  [t(thetas[3]), r`$-\dfrac{\sqrt3}{2}$`, t(Math.asin(Math.sin(thetas[3]))), 'yes'],
], 'Table: for theta equal to pi over 6 and minus pi over 3, sin inverse of sin theta gives theta back. For 5 pi over 6 it gives pi over 6, and for 7 pi over 6 it gives minus pi over 6, because those angles are outside the principal range.', r`$\sin^{-1}(\sin\theta) = \theta$ only for $\theta$ in $\left[-\dfrac{\pi}{2}, \dfrac{\pi}{2}\right]$.`);
const signTable = table(['Expression', 'Where the angle lies', 'Sign of the other ratios'], [
  [r`$\sin^{-1}(\text{negative})$`, r`$\left[-\dfrac{\pi}{2}, 0\right)$`, 'cos positive, tan negative'],
  [r`$\cos^{-1}(\text{negative})$`, r`$\left(\dfrac{\pi}{2}, \pi\right]$`, 'sin positive, tan negative'],
  [r`$\tan^{-1}(\text{negative})$`, r`$\left(-\dfrac{\pi}{2}, 0\right)$`, 'cos positive, sin negative'],
  [r`any of them, positive input`, r`$\left(0, \dfrac{\pi}{2}\right]$`, 'all positive'],
], 'Sign table: sin inverse or tan inverse of a negative number is a negative angle, so its cosine is positive; cos inverse of a negative number is an obtuse angle, so its sine is positive; a positive input always gives an acute angle with all ratios positive.', 'Decide the sign from the principal range before taking a square root.');
const methodFlow = flow('TB', [['s', 'Principal value of an inverse function at $a$'], ['d', 'Is $a$ in the domain?'], ['no', 'Not defined'], ['rg', 'Write the principal range'], ['ref', 'Reference angle with ratio $|a|$'], ['pl', 'Place it in the range using the sign of $a$'], ['ck', 'Check: in the range, correct ratio']], [['s', 'd'], ['d', 'no', 'No'], ['d', 'rg', 'Yes'], ['rg', 'ref'], ['ref', 'pl'], ['pl', 'ck']], 'Flow chart for a principal value: check the input is in the domain, otherwise it is not defined; write the principal range; find the reference angle for the absolute value of the input; place the angle in the range using the sign; check.', 'Four steps for every principal value question.');
const inverseFlow = flow('LR', [['f', 'Function $f$'], ['q', 'One-one and onto?'], ['y', 'Each output from exactly one input: reverse it, $f^{-1}$ exists'], ['n', 'Restrict the domain to a piece where it is one-one and onto'], ['b', 'Principal value branch']], [['f', 'q'], ['q', 'y', 'Yes'], ['q', 'n', 'No'], ['n', 'b']], 'Flow chart: if a function is one-one and onto, each output comes from exactly one input and it can be reversed. If not, restrict the domain to a piece where it is one-one and onto; that piece gives the principal value branch.', 'Trigonometric functions take the "No" route.');
const triTan = geom({
  width: 5.5, height: 4.3,
  points: { A: { at: [0.5, 0.5], label_position: 'sw' }, B: { at: [4.5, 0.5], label_position: 'se' }, C: { at: [4.5, 3.5], label_position: 'ne' } },
  segments: [{ from: 'A', to: 'B', label: '4' }, { from: 'B', to: 'C', label: '3' }, { from: 'A', to: 'C', label: '5' }],
  angles: [{ at: 'A', from: 'B', to: 'C', label: r`$\theta$` }, { at: 'B', from: 'A', to: 'C', right: true }],
}, 'A right triangle ABC with the right angle at B. The side AB next to angle theta is 4, the opposite side BC is 3 and the hypotenuse AC is 5.', r`$\theta = \tan^{-1}\dfrac34$: opposite $3$, adjacent $4$, so hypotenuse $5$ and $\cos\theta = \dfrac45$.`);
{ // self-check: lengths drawn on the stated scale, Pythagoras, and the angle is tan⁻¹(3/4)
  const [A, B, C] = ['A', 'B', 'C'].map((k) => triTan.spec.points[k].at);
  const len = (u, v) => Math.hypot(u[0] - v[0], u[1] - v[1]);
  if (Math.abs(len(A, B) - 4) > 1e-9 || Math.abs(len(B, C) - 3) > 1e-9 || Math.abs(len(A, C) - 5) > 1e-9) throw new Error('triTan lengths');
  if (Math.abs(Math.atan2(C[1] - A[1], C[0] - A[0]) - Math.atan(0.75)) > 1e-12 || Math.abs(Math.cos(Math.atan(0.75)) - 0.8) > 1e-12) throw new Error('triTan angle');
}

// ---------------------------------------------------------------- deck 1
const d1 = deck({
  part: 1,
  title: 'Inverse Trigonometric Functions — Part 1: Principal value branches',
  goals: ['Explain why trigonometric functions must be restricted before they can be inverted', 'State the domain and principal value branch of all six inverse trigonometric functions', 'Find principal values for standard inputs, positive and negative', 'Find the domain of expressions such as the inverse sine of a linear expression'],
  slides: [
    sl('title', 'Inverse Trigonometric Functions, Part 1: Principal values', { b: 'Trigonometry gives a ratio from an angle. Now we go backwards: from a ratio to **one** angle.', v: pReflect, n: 'Welcome. Until now you have found the sine of a given angle. In this chapter we turn the question around. If a sine is one half, what is the angle? There are many answers, so mathematicians agreed on one standard answer, called the principal value. On the screen, the sine curve and its mirror image show how the inverse function is built.' }),
    sl('concept', 'What you will be able to do', { ul: ['Explain why $\\sin x$, $\\cos x$, $\\tan x$ need a **restricted domain** to have inverses', 'State the **domain** and **principal value branch** of all six inverse functions', 'Find **principal values**, including for negative inputs', 'Find the domain of expressions like $\\sin^{-1}(3x - 2)$'], n: 'Here are the goals for part one. By the end you will know the domain and the principal range of each inverse trigonometric function, and you will find principal values quickly and correctly, including the tricky negative inputs that appear in almost every board paper as a one mark question.' }),
    sl('diagram', 'When can a function be reversed?', { b: 'A function can be reversed only if every output comes from **exactly one** input (one-one) and every target value is reached (onto).', v: inverseFlow, n: 'Think of a function as a machine that takes an input to an output. To run it backwards, each output must come from just one input. Otherwise, going back, we would not know which input to choose. Trigonometric functions repeat their values again and again, so they fail this test. The fix is to keep only one suitable piece of the graph.' }),
    sl('diagram', 'Sine is not one-one', { b: 'The line $y = \\dfrac12$ cuts $y = \\sin x$ again and again: $\\sin\\dfrac{\\pi}{6} = \\sin\\dfrac{5\\pi}{6} = \\sin\\left(-\\dfrac{7\\pi}{6}\\right) = \\dfrac12$.', v: pSinFull, n: 'Here is the sine wave with the horizontal line at height one half. It crosses the wave at four points in view, and at infinitely many points altogether. So if someone asks which angle has sine one half, there is no single answer. A horizontal line that cuts a graph more than once tells you the function is not one-one.' }),
    sl('diagram', 'Keep one piece: the principal branch of sine', { b: 'On $\\left[-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right]$, sine increases from $-1$ to $1$, taking each value **once**. This piece is reversed to define $\\sin^{-1}$.', v: pSinRestricted, n: 'Now keep only the piece from minus pi over two to pi over two. On this piece, sine rises steadily from minus one to one. Every value between minus one and one is reached exactly once. So this restricted sine can be reversed. This choice of piece is called the principal value branch.' }),
    sl('concept', 'Definition of the inverse sine', { b: '$\\sin^{-1} x$ (also written $\\arcsin x$) is **the angle in** $\\left[-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right]$ **whose sine is** $x$.', m: ['y = \\sin^{-1} x \\iff \\sin y = x \\ \\text{ and } \\ -\\dfrac{\\pi}{2} \\le y \\le \\dfrac{\\pi}{2}'], ul: ['Domain: $[-1, 1]$', 'Range (principal value branch): $\\left[-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right]$', '$\\sin^{-1} x$ is **not** $\\dfrac{1}{\\sin x}$'], v: sinValTable, n: 'So sine inverse of x is the angle between minus pi over two and pi over two whose sine is x. Both conditions matter: the right sine, and the right range. The input must lie between minus one and one. Be careful: the minus one is not a power here. Sine inverse of x is an angle, not one divided by sine x.' }),
    sl('check', 'Quick check: the range of the inverse sine', { b: 'Choose the principal value branch of $\\sin^{-1}$.', chk: 'm01', n: 'Pause and choose. Remember the piece of the sine graph we kept, and which angles it covers. Watch out for an option that is really the domain.' }),
    sl('example', 'Worked example 1: a negative input', { b: 'Find the principal value of $\\sin^{-1}\\left(-\\dfrac12\\right)$.', ul: ['**Step 1 —** Range: $\\left[-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right]$.', '**Step 2 —** Reference angle: $\\sin\\dfrac{\\pi}{6} = \\dfrac12$.', '**Step 3 —** The input is negative, so take the negative angle: $\\sin\\left(-\\dfrac{\\pi}{6}\\right) = -\\dfrac12$.', '**Answer —** $-\\dfrac{\\pi}{6}$, which lies in the range. ($\\dfrac{7\\pi}{6}$ also has sine $-\\dfrac12$ but is outside the range.)'], v: pWE1, n: 'Start by writing the range. The reference angle with sine one half is pi over six. Our input is negative, and in this range negative sines belong to negative angles, so the answer is minus pi over six. Seven pi over six also has sine minus one half, but it lies outside the range, so it is not the principal value.' }),
    sl('diagram', 'The principal branch of cosine', { b: 'Cosine is one-one on $[0, \\pi]$: it falls from $1$ to $-1$, taking each value once.', v: pCosRestricted, n: 'For cosine we cannot use the same piece as sine, because cosine is not one-one there: cosine of minus pi over three equals cosine of pi over three. Instead we keep the piece from zero to pi. Here cosine falls steadily from one to minus one, reaching each value exactly once.' }),
    sl('concept', 'Definition of the inverse cosine', { b: '$\\cos^{-1} x$ is **the angle in** $[0, \\pi]$ **whose cosine is** $x$.', m: ['y = \\cos^{-1} x \\iff \\cos y = x \\ \\text{ and } \\ 0 \\le y \\le \\pi'], ul: ['Domain: $[-1, 1]$', 'Range: $[0, \\pi]$ — never negative', 'Negative input → angle between $\\dfrac{\\pi}{2}$ and $\\pi$'], v: cosValTable, n: 'Cos inverse of x is the angle between zero and pi whose cosine is x. Its values are never negative. When the input is negative, the angle is obtuse, between pi over two and pi. This is the most common place to lose a mark: writing a negative angle for cos inverse of a negative number.' }),
    sl('example', 'Worked example 2: cos inverse of a negative number', { b: 'Find the principal value of $\\cos^{-1}\\left(-\\dfrac{1}{\\sqrt2}\\right)$.', ul: ['**Step 1 —** Range: $[0, \\pi]$.', '**Step 2 —** Reference angle: $\\cos\\dfrac{\\pi}{4} = \\dfrac{1}{\\sqrt2}$.', '**Step 3 —** Negative cosine in $[0, \\pi]$ means the second quadrant: $\\pi - \\dfrac{\\pi}{4} = \\dfrac{3\\pi}{4}$.', '**Answer —** $\\dfrac{3\\pi}{4}$. (Not $-\\dfrac{\\pi}{4}$: negative angles are outside the range.)'], v: pWE2, n: 'Write the range, zero to pi. The reference angle with cosine one over root two is pi over four. The input is negative, so the angle must be in the second quadrant, which is pi minus pi over four, that is three pi over four. The graph confirms it: the point sits above pi over two.' }),
    sl('diagram', 'The principal branch of tangent', { b: 'Tangent is one-one on the **open** interval $\\left(-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right)$ and takes **every** real value there.', v: pTanRestricted, n: 'Tangent is undefined at plus and minus pi over two, so its piece is the open interval between them. On this piece, tangent rises from very large negative values to very large positive values, taking every real value once. So tan inverse accepts any real number, and its answer always lies strictly between minus pi over two and pi over two.' }),
    sl('check', 'Quick check: the domain of the inverse tangent', { b: 'True or false: $\\tan^{-1} x$ is defined for every real $x$?', chk: 'tf1', n: 'Look back at the tangent piece. Which outputs did it reach? Those outputs become the allowed inputs of tan inverse.' }),
    sl('concept', 'All six principal value branches', { b: 'The other three inverses use the same idea. $\\operatorname{cosec}^{-1}$ and $\\sec^{-1}$ need $|x| \\ge 1$.', v: branchTable, n: 'Here are all six. Sine inverse and cos inverse take inputs from minus one to one. Tan inverse and cot inverse take every real number. Cosec inverse and sec inverse take numbers outside the open interval from minus one to one. Notice cot inverse has range zero to pi, not the tangent range. Learn this table well: every principal value question uses one row.' }),
    sl('example', 'Worked example 3: cot inverse and cosec inverse', { b: 'Find the principal values of $\\cot^{-1}(-\\sqrt3)$ and $\\operatorname{cosec}^{-1}\\left(\\dfrac{2}{\\sqrt3}\\right)$.', ul: ['**cot:** range $(0, \\pi)$. $\\cot\\dfrac{\\pi}{6} = \\sqrt3$; negative, so second quadrant: $\\pi - \\dfrac{\\pi}{6} = \\dfrac{5\\pi}{6}$.', '**cosec:** $\\operatorname{cosec} y = \\dfrac{2}{\\sqrt3}$ means $\\sin y = \\dfrac{\\sqrt3}{2}$; in the range, $y = \\dfrac{\\pi}{3}$.', '**Trap —** $-\\dfrac{\\pi}{6}$ has cotangent $-\\sqrt3$ but is **not** in $(0, \\pi)$.'], v: otherTable, n: 'For cot inverse the range is zero to pi, so a negative input gives a second quadrant angle: five pi over six, not minus pi over six. For cosec inverse, change cosecant to sine by taking the reciprocal of the given number, then find the angle in the sine range. Here that is pi over three.' }),
    sl('check', 'Quick check: cosec inverse', { b: 'Find the principal value of $\\operatorname{cosec}^{-1}(-\\sqrt2)$.', chk: 'm08', n: 'Change to sine first. Then use the range minus pi over two to pi over two, without zero. A negative input means a negative angle.' }),
    sl('diagram', 'A method for every principal value', { b: 'Domain → range → reference angle → sign → check.', v: methodFlow, n: 'Here is a routine that always works. First check that the input is allowed. Then write the principal range. Find the reference angle using the size of the input. Use the sign of the input to place the angle in the range. Finally check both conditions: the right ratio, and inside the range.' }),
    sl('example', 'Worked example 4: domain of an inverse expression', { b: 'Find the domain of $f(x) = \\cos^{-1}(3 - 2x)$.', ul: ['**Step 1 —** The input of $\\cos^{-1}$ must be in $[-1, 1]$: $-1 \\le 3 - 2x \\le 1$.', '**Step 2 —** Subtract $3$: $-4 \\le -2x \\le -2$.', '**Step 3 —** Divide by $-2$ and **reverse** the signs: $2 \\ge x \\ge 1$.', '**Answer —** Domain $[1, 2]$.'], v: pDomain, n: 'The whole expression inside cos inverse must lie between minus one and one. Write that as a double inequality and solve it. Subtract three from all parts, then divide by minus two, remembering to reverse the inequality signs. So x lies from one to two. The graph shows the input line staying between the dashed levels exactly there.' }),
    sl('check', 'Quick check: a principal value', { b: 'Fill in: the principal value of $\\cos^{-1}\\left(\\dfrac{1}{\\sqrt2}\\right)$.', chk: 'fb2', n: 'A positive input to cos inverse gives an acute angle. Which acute angle has cosine one over root two?' }),
    sl('summary', 'Summary', { ul: ['Trigonometric functions are not one-one; restrict each to a **principal value branch**', '$\\sin^{-1}$: $[-1, 1] \\to \\left[-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right]$; $\\cos^{-1}$: $[-1, 1] \\to [0, \\pi]$; $\\tan^{-1}$: $\\mathbb{R} \\to \\left(-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right)$', '$\\cot^{-1}$: $(0, \\pi)$; $\\sec^{-1}$: $[0, \\pi]$ without $\\dfrac{\\pi}{2}$; $\\operatorname{cosec}^{-1}$: $\\left[-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right]$ without $0$', 'Principal value: right ratio **and** inside the range', 'Domain of $\\sin^{-1}(u)$ or $\\cos^{-1}(u)$: solve $-1 \\le u \\le 1$'], v: branchTable, n: 'To sum up. Each trigonometric function is restricted to a piece where it is one-one, and that piece defines the inverse. A principal value must have the right ratio and lie in the principal range. For cos inverse and cot inverse, negative inputs give obtuse angles. For sine inverse, tan inverse and cosec inverse, negative inputs give negative angles.' }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: ['**Principal value (1–2 marks):** range stated 1 + correct value 1', '**Evaluate a combination (2–3 marks):** each principal value 1 + combined answer 1', '**Domain (2–3 marks):** inequality $-1 \\le u \\le 1$ 1 + solving 1 + interval 1', '**Mistake:** $\\cos^{-1}\\left(-\\dfrac12\\right) = -\\dfrac{\\pi}{3}$ (must be $\\dfrac{2\\pi}{3}$)', '**Mistakes:** reading $\\sin^{-1} x$ as $\\dfrac{1}{\\sin x}$; not reversing an inequality after dividing by a negative number', '**Note:** properties of inverse trigonometric functions are not in the 2026–27 syllabus; work from the branches'], n: 'Examiners give a mark for stating or using the correct range, and a mark for the value. In combinations, each principal value earns credit, so write them separately before adding. The classic errors are a negative angle for cos inverse, treating the minus one as a reciprocal, and not reversing an inequality.' }),
  ],
});

// ---------------------------------------------------------------- deck 2
const d2 = deck({
  part: 2,
  title: 'Inverse Trigonometric Functions — Part 2: Graphs and evaluating expressions',
  goals: ['Draw the graphs of the inverse sine, cosine and tangent by reflecting the restricted graphs', 'Read domain, range, increasing or decreasing, and asymptotes from the graphs', 'Evaluate expressions such as the inverse sine of the sine of an angle using the principal branch', 'Evaluate a trigonometric ratio of an inverse trigonometric value with a right triangle and the correct sign', 'Solve simple equations involving inverse trigonometric functions'],
  slides: [
    sl('title', 'Inverse Trigonometric Functions, Part 2: Graphs', { b: 'Three graphs, three shapes — and every principal value is a point on one of them.', v: pAll3, n: 'Welcome to part two. Here are the graphs of sine inverse, cos inverse and tan inverse on one set of axes. Two of them are short curves, because their inputs must lie between minus one and one. Tan inverse runs across the whole picture. By the end of this part you will draw these graphs and use them to reason.' }),
    sl('concept', 'What you will be able to do', { ul: ['Draw $y = \\sin^{-1} x$, $y = \\cos^{-1} x$, $y = \\tan^{-1} x$ by **reflection in** $y = x$', 'Read domain, range, increasing/decreasing and asymptotes', 'Evaluate $\\sin^{-1}(\\sin\\theta)$ and similar using the principal branch', 'Evaluate expressions like $\\cos\\left(\\tan^{-1}\\dfrac34\\right)$ with a triangle and the right sign', 'Solve equations such as $\\tan^{-1}(3x) = -\\dfrac{\\pi}{3}$'], n: 'Here are the goals for part two. You will draw the three main graphs by reflection, read their features, and evaluate expressions that combine a trigonometric function with an inverse one. These appear in board papers as one mark questions, two mark short answers and case studies.' }),
    sl('diagram', 'Inverse graph = reflection in the line y = x', { b: 'If $(a, b)$ is on the restricted graph of $\\cos x$, then $(b, a)$ is on $y = \\cos^{-1} x$.', v: pReflectCos, n: 'An inverse function swaps inputs and outputs. So every point a comma b on the restricted cosine graph becomes the point b comma a on the cos inverse graph. Swapping coordinates is the same as reflecting in the line y equals x. Look at the pairs: zero comma one becomes one comma zero, and pi comma minus one becomes minus one comma pi.' }),
    sl('diagram', 'The graph of the inverse sine', { b: 'Reflect the sine piece on $\\left[-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right]$ in $y = x$.', v: pAsin, n: 'Reflecting the restricted sine curve gives the graph of sine inverse. It starts at minus one comma minus pi over two, passes through the origin, and ends at one comma pi over two. It is increasing all the way, steep near the ends and flatter near the middle. Plot the five marked points and join them smoothly.' }),
    sl('concept', 'Reading a graph of an inverse function', { ul: ['**Domain:** how far the curve reaches left and right', '**Range:** how far it reaches down and up — the principal branch', '**Increasing/decreasing:** $\\sin^{-1}$ and $\\tan^{-1}$ rise; $\\cos^{-1}$ falls', '**End points / asymptotes:** $\\sin^{-1}$ and $\\cos^{-1}$ have end points; $\\tan^{-1}$ has horizontal asymptotes', '**Use:** larger input on a rising graph gives a larger angle'], n: 'When you read a graph, ask four questions. How far left and right does it go? That is the domain. How far down and up? That is the range. Does it rise or fall? And does it stop at end points or approach lines without touching? These features answer many graph questions without any calculation.' }),
    sl('diagram', 'The graph of the inverse cosine', { b: 'Reflect the cosine piece on $[0, \\pi]$: the graph **falls** from $(-1, \\pi)$ to $(1, 0)$.', v: pAcos, n: 'The cos inverse graph starts high, at minus one comma pi, passes through zero comma pi over two, and falls to one comma zero. It never goes below the x axis, because cos inverse is never negative. It is a decreasing function: larger inputs give smaller angles.' }),
    sl('check', 'Quick check: rising or falling?', { b: 'True or false: $y = \\cos^{-1} x$ is decreasing on $[-1, 1]$.', chk: 'tf4', n: 'Picture the graph you have just seen. As you move from left to right, does it go up or down?' }),
    sl('diagram', 'The graph of the inverse tangent', { b: 'Domain $\\mathbb{R}$; the curve rises through the origin and flattens towards $y = \\pm\\dfrac{\\pi}{2}$ without reaching them.', v: pAtanDeck, n: 'Reflecting the tangent piece, its vertical asymptotes become horizontal ones. So the tan inverse graph is an S shape through the origin that gets closer and closer to the lines y equals pi over two and y equals minus pi over two, but never touches them. That is why its range is an open interval.' }),
    sl('check', 'Quick check: identify the graph', { b: 'A curve passes through $(-1, \\pi)$, $\\left(0, \\dfrac{\\pi}{2}\\right)$ and $(1, 0)$. Which function is it?', chk: 'm15', n: 'Test each option at the three points. Which inverse function is pi at minus one and zero at one?' }),
    sl('example', 'Worked example 5: compare without a calculator', { b: 'Which is larger: $\\sin^{-1} 0.8$ or $\\sin^{-1} 0.6$?', ul: ['**Step 1 —** Both inputs are in $[-1, 1]$, so both are defined.', '**Step 2 —** $y = \\sin^{-1} x$ is **increasing**.', '**Step 3 —** $0.8 > 0.6$, so $\\sin^{-1} 0.8 > \\sin^{-1} 0.6$.', '**Note —** For $\\cos^{-1}$, which decreases, the order reverses: $\\cos^{-1} 0.8 < \\cos^{-1} 0.6$.'], v: pWE5, n: 'You do not need the actual angles. The sine inverse graph is increasing, so a larger input gives a larger angle. Point Q at zero point eight is higher than point P at zero point six. For cos inverse the graph falls, so the order of the angles is reversed.' }),
    sl('concept', 'Inside-out: the inverse of the function of an angle', { b: 'To find $\\sin^{-1}(\\sin\\theta)$: first work out $\\sin\\theta$, then find the principal value. You get $\\theta$ back **only** if $\\theta$ is in the principal range.', v: compTable, n: 'Students often cancel sine inverse and sine and write theta. That only works when theta is already in the principal range. Otherwise, work from the inside out. Find the sine of theta first, then find the principal value of that number. The table shows angles that come back unchanged, and angles that do not.' }),
    sl('example', 'Worked example 6: an angle outside the range', { b: 'Evaluate $\\sin^{-1}\\left(\\sin\\dfrac{7\\pi}{10}\\right)$.', ul: ['**Step 1 —** $\\dfrac{7\\pi}{10}$ is **not** in $\\left[-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right]$, so the answer is not $\\dfrac{7\\pi}{10}$.', '**Step 2 —** $\\sin\\dfrac{7\\pi}{10} = \\sin\\left(\\pi - \\dfrac{7\\pi}{10}\\right) = \\sin\\dfrac{3\\pi}{10}$.', '**Step 3 —** $\\dfrac{3\\pi}{10}$ **is** in the range and has the same sine.', `**Answer —** ${t(Math.asin(Math.sin(7 * P / 10)))}.`], v: pWE6, n: 'Seven pi over ten is bigger than pi over two, so it is outside the sine inverse range. On the sine arch, the angle three pi over ten has exactly the same height, mirrored in the line x equals pi over two. And three pi over ten is inside the range. So the answer is three pi over ten.' }),
    sl('check', 'Quick check: tangent of an angle outside the range', { b: 'Evaluate $\\tan^{-1}\\left(\\tan\\dfrac{5\\pi}{6}\\right)$.', chk: 'm11', n: 'Is five pi over six inside the open interval from minus pi over two to pi over two? If not, find the tangent first, then the principal value.' }),
    sl('diagram', 'Outside-in: a ratio of an inverse value', { b: 'To find $\\cos\\left(\\tan^{-1}\\dfrac34\\right)$, name the angle $\\theta = \\tan^{-1}\\dfrac34$ and draw its right triangle.', v: triTan, n: 'Now the other way round: a trigonometric ratio of an inverse value. Call the angle theta. Tan theta is three over four, and theta is acute because the input is positive. Draw a right triangle with opposite three and adjacent four. The hypotenuse is five, so cos theta is four over five.' }),
    sl('example', 'Worked example 7: the sign matters', { b: 'Find $\\sin\\left(\\cos^{-1}\\left(-\\dfrac{5}{13}\\right)\\right)$.', ul: ['**Step 1 —** $\\alpha = \\cos^{-1}\\left(-\\dfrac{5}{13}\\right)$ is in $\\left(\\dfrac{\\pi}{2}, \\pi\\right)$ (negative input).', '**Step 2 —** In that interval sine is **positive**.', '**Step 3 —** $\\sin\\alpha = \\sqrt{1 - \\dfrac{25}{169}} = \\dfrac{12}{13}$.', '**Answer —** $\\dfrac{12}{13}$ (not $-\\dfrac{12}{13}$).'], v: signTable, n: 'First place the angle. Cos inverse of a negative number is an obtuse angle, in the second quadrant, where sine is positive. Then use the triangle or the identity sine squared plus cos squared equals one to get twelve over thirteen. The sign comes from the range, not from the minus in the question.' }),
    sl('example', 'Worked example 8: solving an equation', { b: 'Solve $\\tan^{-1}(3x) = -\\dfrac{\\pi}{3}$.', ul: ['**Step 1 —** $-\\dfrac{\\pi}{3}$ is in $\\left(-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right)$, so a solution can exist.', '**Step 2 —** By definition, $3x = \\tan\\left(-\\dfrac{\\pi}{3}\\right) = -\\sqrt3$.', '**Step 3 —** $x = -\\dfrac{\\sqrt3}{3} = -\\dfrac{1}{\\sqrt3}$.', '**Warning —** $\\cos^{-1} x = -\\dfrac{\\pi}{3}$ has **no** solution: the right side is outside $[0, \\pi]$.'], v: pWE8, n: 'Before solving, check that the right side lies in the principal range. Here it does. Then apply tangent to both sides, which is exactly the definition of tan inverse. Three x equals minus root three, so x equals minus one over root three. If the right side were outside the range, the equation would have no solution.' }),
    sl('check', 'Quick check: the reflection', { b: 'How is the graph of $y = \\cos^{-1} x$ obtained from the restricted cosine graph?', chk: 'm17', n: 'Remember what an inverse does to each point: it swaps the input and the output. Which reflection swaps coordinates?' }),
    sl('summary', 'Summary', { ul: ['Graph of an inverse = reflection of the restricted graph in $y = x$', '$\\sin^{-1}$: rising, ends $\\left(\\pm 1, \\pm\\dfrac{\\pi}{2}\\right)$; $\\cos^{-1}$: falling, from $(-1, \\pi)$ to $(1, 0)$', '$\\tan^{-1}$: rising, all real inputs, asymptotes $y = \\pm\\dfrac{\\pi}{2}$', '$f^{-1}(f(\\theta)) = \\theta$ only if $\\theta$ is in the principal range; otherwise work inside-out', 'Ratio of an inverse value: name the angle, place it by its range, use a triangle'], v: pAll3, n: 'To sum up. Each inverse graph is the mirror image of its restricted graph in the line y equals x. Sine inverse and tan inverse rise; cos inverse falls. Tan inverse has horizontal asymptotes. When an inverse acts on a trigonometric value, work from the inside out. When a ratio acts on an inverse value, name the angle, place it, and use a triangle.' }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: ['**Graph (3–5 marks):** table of at least five correct points 1 + shape and end points 1 + domain and range 1 + features asked 1–2', '**Inside-out (1–3 marks):** inner value 1 + principal value with the range named 1', '**Ratio of an inverse value (2–3 marks):** angle placed in its range 1 + triangle or identity 1 + value with sign 1', '**Mistake:** cancelling: $\\sin^{-1}\\left(\\sin\\dfrac{5\\pi}{6}\\right) = \\dfrac{5\\pi}{6}$', '**Mistake:** drawing $\\cos^{-1}$ below the $x$-axis or $\\tan^{-1}$ crossing $y = \\dfrac{\\pi}{2}$', '**Mistake:** losing the sign: $\\sin\\left(\\cos^{-1}(\\text{negative})\\right)$ is positive'], n: 'In graph questions, a clear table of values with exact angles earns the first mark, so write it down. In inside-out questions, always write the inner value before the principal value. For ratios of inverse values, say where the angle lies before taking a square root. The usual slips are cancelling outside the range and losing a sign.' }),
  ],
});

// ---------------------------------------------------------------- notes
const notes = {
  unit: 'cbse-12-mathematics-ch02', version: 1, title: 'Inverse Trigonometric Functions — chapter notes', language: 'en',
  sections: [
    { heading: '1. Why the domain must be restricted', body_md: 'A function has an inverse only if it is **one-one** (each output from exactly one input) and **onto** its target set. Trigonometric functions are periodic, so every value is taken infinitely often: $\\sin\\dfrac{\\pi}{6} = \\sin\\dfrac{5\\pi}{6} = \\sin\\dfrac{13\\pi}{6} = \\dfrac12$. A horizontal line that cuts a graph more than once shows that the function is not one-one.\n\nThe fix is to keep one piece of the graph on which the function is one-one and still takes all its values. That piece defines the **principal value branch**, and the value returned is the **principal value**. Other branches exist (for example $\\left[\\dfrac{\\pi}{2}, \\dfrac{3\\pi}{2}\\right]$ for sine), but unless stated otherwise we always use the principal branch.', key_terms: [{ term: 'One-one (injective)', definition_md: 'Different inputs always give different outputs.' }, { term: 'Principal value branch', definition_md: 'The agreed interval on which a trigonometric function is restricted so that its inverse is a function.' }, { term: 'Principal value', definition_md: 'The value of an inverse trigonometric function that lies in its principal value branch.' }], formulas: [], visual: pSinFull, topic_ids: [topic(1)] },
    { heading: '2. Inverse sine', body_md: 'On $\\left[-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right]$, $\\sin x$ increases from $-1$ to $1$. Its inverse is $\\sin^{-1}$ (also $\\arcsin$):\n\n$y = \\sin^{-1} x$ means $\\sin y = x$ **and** $-\\dfrac{\\pi}{2} \\le y \\le \\dfrac{\\pi}{2}$.\n\n- Domain $[-1, 1]$; range $\\left[-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right]$.\n- Negative input gives a negative angle: $\\sin^{-1}\\left(-\\dfrac12\\right) = -\\dfrac{\\pi}{6}$.\n- $\\sin^{-1} x \\ne \\dfrac{1}{\\sin x}$; the reciprocal is $(\\sin x)^{-1} = \\operatorname{cosec} x$.', key_terms: [{ term: 'Inverse sine', definition_md: '$\\sin^{-1} x$: the angle in $\\left[-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right]$ whose sine is $x$.' }], formulas: [{ latex: 'y = \\sin^{-1} x \\iff \\sin y = x,\\ -\\dfrac{\\pi}{2} \\le y \\le \\dfrac{\\pi}{2}', label: 'Definition' }], visual: sinValTable, topic_ids: [topic(1)] },
    { heading: '3. Inverse cosine and inverse tangent', body_md: '**Cosine** is one-one on $[0, \\pi]$, falling from $1$ to $-1$. So $y = \\cos^{-1} x$ means $\\cos y = x$ and $0 \\le y \\le \\pi$. Domain $[-1, 1]$; range $[0, \\pi]$. Values are never negative; a negative input gives an obtuse angle: $\\cos^{-1}\\left(-\\dfrac12\\right) = \\dfrac{2\\pi}{3}$.\n\n**Tangent** is one-one on the open interval $\\left(-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right)$ and takes every real value there. So $y = \\tan^{-1} x$ means $\\tan y = x$ and $-\\dfrac{\\pi}{2} < y < \\dfrac{\\pi}{2}$. Domain $\\mathbb{R}$; range the **open** interval $\\left(-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right)$. Example: $\\tan^{-1}(-\\sqrt3) = -\\dfrac{\\pi}{3}$.', key_terms: [{ term: 'Inverse cosine', definition_md: '$\\cos^{-1} x$: the angle in $[0, \\pi]$ whose cosine is $x$.' }, { term: 'Inverse tangent', definition_md: '$\\tan^{-1} x$: the angle in $\\left(-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right)$ whose tangent is $x$.' }], formulas: [{ latex: 'y = \\cos^{-1} x \\iff \\cos y = x,\\ 0 \\le y \\le \\pi', label: 'Inverse cosine' }, { latex: 'y = \\tan^{-1} x \\iff \\tan y = x,\\ -\\dfrac{\\pi}{2} < y < \\dfrac{\\pi}{2}', label: 'Inverse tangent' }], visual: cosValTable, topic_ids: [topic(1)] },
    { heading: '4. The other three branches', body_md: '- $\\operatorname{cosec}^{-1} x$: domain $\\mathbb{R} - (-1, 1)$ (that is, $|x| \\ge 1$); range $\\left[-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right] - \\{0\\}$.\n- $\\sec^{-1} x$: domain $\\mathbb{R} - (-1, 1)$; range $[0, \\pi] - \\left\\{\\dfrac{\\pi}{2}\\right\\}$.\n- $\\cot^{-1} x$: domain $\\mathbb{R}$; range $(0, \\pi)$.\n\nTo find such a value, change to the reciprocal ratio and use the range: $\\sec y = -2$ means $\\cos y = -\\dfrac12$ with $y \\in [0, \\pi]$, so $\\sec^{-1}(-2) = \\dfrac{2\\pi}{3}$. Note that $\\cot^{-1}$ uses $(0, \\pi)$, **not** the tangent range: $\\cot^{-1}(-1) = \\dfrac{3\\pi}{4}$.', key_terms: [{ term: 'Excluded value', definition_md: '$0$ is left out of the cosec-inverse range and $\\dfrac{\\pi}{2}$ out of the sec-inverse range, because cosec and sec are undefined there.' }], formulas: [], visual: branchTable, topic_ids: [topic(1)] },
    { heading: '5. Finding principal values and domains', body_md: '**Principal value of an inverse function at $a$:**\n1. Check that $a$ is in the domain (otherwise "not defined").\n2. Write the principal range.\n3. Find the reference angle whose ratio is $|a|$.\n4. Use the sign of $a$ to place the angle in the range.\n5. Check: correct ratio and inside the range.\n\n**Combinations** such as $2\\cos^{-1}(0) - 3\\tan^{-1}(1) + \\sin^{-1}\\left(\\dfrac12\\right)$: find each principal value separately, then combine: $\\pi - \\dfrac{3\\pi}{4} + \\dfrac{\\pi}{6} = \\dfrac{5\\pi}{12}$.\n\n**Domains:** for $\\sin^{-1}(u)$ or $\\cos^{-1}(u)$ solve $-1 \\le u \\le 1$. Example: $\\cos^{-1}(3 - 2x)$ needs $1 \\le x \\le 2$. With several terms, intersect the conditions.', key_terms: [{ term: 'Reference angle', definition_md: 'The acute angle whose ratio equals the size of the given value.' }], formulas: [{ latex: '\\text{domain of } \\sin^{-1}(u),\\ \\cos^{-1}(u):\\ -1 \\le u \\le 1', label: 'Domain condition' }], visual: methodFlow, topic_ids: [topic(1)] },
    { heading: '6. Graphs of the inverse functions', body_md: 'The graph of an inverse function is the **reflection** of the restricted graph in the line $y = x$, because each point $(a, b)$ becomes $(b, a)$.\n\n| Graph | Shape | Key points |\n|---|---|---|\n| $y = \\sin^{-1} x$ | rising, end points | $\\left(-1, -\\dfrac{\\pi}{2}\\right)$, $(0, 0)$, $\\left(1, \\dfrac{\\pi}{2}\\right)$ |\n| $y = \\cos^{-1} x$ | falling, end points, never below the $x$-axis | $(-1, \\pi)$, $\\left(0, \\dfrac{\\pi}{2}\\right)$, $(1, 0)$ |\n| $y = \\tan^{-1} x$ | rising, all real $x$, asymptotes $y = \\pm\\dfrac{\\pi}{2}$ | $(0, 0)$, $\\left(1, \\dfrac{\\pi}{4}\\right)$ |\n\nUses: compare values without a calculator ($\\sin^{-1} 0.8 > \\sin^{-1} 0.6$ because the graph rises; $\\cos^{-1} 0.8 < \\cos^{-1} 0.6$ because it falls); solve inequalities such as $\\cos^{-1} x > \\dfrac{\\pi}{3} \\iff -1 \\le x < \\dfrac12$.', key_terms: [{ term: 'Horizontal asymptote', definition_md: 'A line $y = c$ that a graph approaches but never reaches, e.g. $y = \\dfrac{\\pi}{2}$ for $y = \\tan^{-1} x$.' }], formulas: [], visual: pAll3, visuals: [pReflectCos, gAtan], topic_ids: [topic(2)] },
    { heading: '7. Evaluating compositions', body_md: '**Inside-out, $\\sin^{-1}(\\sin\\theta)$:** equals $\\theta$ only if $\\theta \\in \\left[-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right]$. Otherwise evaluate $\\sin\\theta$ first and take the principal value: $\\sin^{-1}\\left(\\sin\\dfrac{5\\pi}{6}\\right) = \\sin^{-1}\\dfrac12 = \\dfrac{\\pi}{6}$. Likewise $\\cos^{-1}(\\cos\\theta) = \\theta$ only on $[0, \\pi]$, and $\\tan^{-1}(\\tan\\theta) = \\theta$ only on $\\left(-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right)$.\n\n**Outside-in, $\\cos\\left(\\tan^{-1}\\dfrac34\\right)$:** name $\\theta = \\tan^{-1}\\dfrac34$, place it by its range (acute here), draw a right triangle $3$–$4$–$5$: $\\cos\\theta = \\dfrac45$. For a negative input, decide the sign from the range: $\\sin\\left(\\cos^{-1}\\left(-\\dfrac{5}{13}\\right)\\right) = \\dfrac{12}{13}$ (positive, second quadrant).\n\n**Equations:** $\\tan^{-1}(3x) = -\\dfrac{\\pi}{3}$ gives $3x = -\\sqrt3$, $x = -\\dfrac{1}{\\sqrt3}$. First check that the right side lies in the range: $\\cos^{-1} x = -\\dfrac{\\pi}{3}$ has no solution.', key_terms: [{ term: 'Inside-out evaluation', definition_md: 'Work out the inner trigonometric value first, then its principal value.' }], formulas: [{ latex: '\\sin^{-1}(\\sin\\theta) = \\theta \\ \\text{ only for } \\ -\\dfrac{\\pi}{2} \\le \\theta \\le \\dfrac{\\pi}{2}', label: 'When an inverse undoes' }], visual: triTan, visuals: [compTable, signTable], topic_ids: [topic(1)] },
  ],
  exam_tips_md: '**How marks are awarded**\n- *Principal value (1–2 marks):* principal range stated or used 1 + value 1.\n- *Combination of values (2–3 marks):* each principal value 1 + combined result 1.\n- *Domain of an expression (2–3 marks):* inequality $-1 \\le u \\le 1$, solving (reverse the sign when dividing by a negative), interval; intersection when there are two terms.\n- *Graph (3–5 marks):* table of at least five exact points, correct shape with end points or asymptotes, domain and range, features asked.\n- *Ratio of an inverse value (2–3 marks):* angle placed by its range, triangle or identity, value with the correct sign.\n\n**Common mistakes**\n1. Giving a negative angle for $\\cos^{-1}$ or $\\cot^{-1}$ of a negative number ($\\cos^{-1}\\left(-\\dfrac12\\right) = \\dfrac{2\\pi}{3}$, not $-\\dfrac{\\pi}{3}$).\n2. Reading $\\sin^{-1} x$ as $\\dfrac{1}{\\sin x}$.\n3. Cancelling $\\sin^{-1}(\\sin\\theta) = \\theta$ when $\\theta$ is outside the principal range.\n4. Using the tangent range $\\left(-\\dfrac{\\pi}{2}, \\dfrac{\\pi}{2}\\right)$ for $\\cot^{-1}$.\n5. Not reversing an inequality after dividing by a negative number when finding a domain.\n6. Drawing $\\tan^{-1}$ crossing $y = \\dfrac{\\pi}{2}$, or $\\cos^{-1}$ below the $x$-axis.\n7. Losing the sign in $\\tan\\left(\\cos^{-1}(\\text{negative})\\right)$, which is negative.\n8. Using properties of inverse trigonometric functions: they are not in the 2026–27 syllabus, and every question here can be done from the branches.',
  status: 'draft', provenance: d1.provenance,
};

